{"hypotheses": [
  {
    "name": "Quality Value in Calm Markets",
    "mechanism": "Combining operating profitability (OperProf), book-to-market (BM), and earnings consistency (EarningsConsistency) should capture stocks that are both high quality and undervalued, outperforming especially when risk aversion is low. The joint signal exploits mispricing in quality and value that is less aggressively arbitraged when volatility is subdued.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "OperProf"},
        {"weight": 1.0, "primitive": "BM"},
        {"weight": 0.5, "primitive": "EarningsConsistency"}
      ],
      "regime": "VIX_BELOW_TRAILING_MEDIAN",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "VIX_BELOW_TRAILING_MEDIAN", "direction": "higher"},
      {"type": "size_segment", "segment": "large", "direction": "stronger"},
      {"type": "correlation", "primitive": "OperProf", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 1.0,
    "expected_decay_half_life_months": 30
  },
  {
    "name": "Analyst Disagreement with Downside Protection",
    "mechanism": "Stocks with high analyst forecast dispersion (ForecastDispersion) but positive recent momentum (Mom12m) and low beta (Beta) are likely to be underappreciated winners, with the low beta term acting as downside risk control. The composite exploits investor underreaction to positive signals in controversial but less risky stocks.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "ForecastDispersion"},
        {"weight": 0.5, "primitive": "Mom12m"},
        {"weight": -0.5, "primitive": "Beta"}
      ],
      "regime": null,
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "size_segment", "segment": "small", "direction": "stronger"},
      {"type": "correlation", "primitive": "Mom12m", "bound": "below", "threshold": 0.3},
      {"type": "international", "region": "emerging", "direction": "same_sign"}
    ],
    "expected_annualized_sharpe": 0.7,
    "expected_decay_half_life_months": 18
  },
  {
    "name": "Capital Discipline under Tight Credit",
    "mechanism": "Firms with high cash flow to price (cfp), low net external financing (XFIN), and low debt issuance (DebtIssuance) display disciplined capital management, which is especially valuable when the term spread is negative and credit conditions are tight. This combination targets credit-constrained mispricings.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "cfp"},
        {"weight": -0.5, "primitive": "XFIN"},
        {"weight": -0.5, "primitive": "DebtIssuance"}
      ],
      "regime": "TERM_SPREAD_NEGATIVE",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "TERM_SPREAD_NEGATIVE", "direction": "higher"},
      {"type": "size_segment", "segment": "small", "direction": "stronger"},
      {"type": "subperiod_consistency"}
    ],
    "expected_annualized_sharpe": 0.8,
    "expected_decay_half_life_months": 24
  },
  {
    "name": "Inventory and Organizational Capital Synergy",
    "mechanism": "Firms with positive changes in inventory (ChInv), high organizational capital (OrgCap), and strong intermediate momentum (IntMom) are positioned to benefit from both internal efficiency and market recognition, as inventory build-ups are less likely to signal negative demand when backed by superior organization and recent price strength.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "ChInv"},
        {"weight": 0.5, "primitive": "OrgCap"},
        {"weight": 0.5, "primitive": "IntMom"}
      ],
      "regime": null,
      "vol_target": false
    },
    "auxiliary_predictions": [
      {"type": "correlation", "primitive": "ChInv", "bound": "below", "threshold": 0.3},
      {"type": "international", "region": "developed_ex_us", "direction": "same_sign"},
      {"type": "size_segment", "segment": "large", "direction": "stronger"}
    ],
    "expected_annualized_sharpe": 0.6,
    "expected_decay_half_life_months": 15
  },
  {
    "name": "Contrarian Quality under Market Downtrends",
    "mechanism": "High gross profits (GP) and low recent momentum (Mom12mOffSeason) together select quality stocks temporarily out of favor, which tend to mean revert especially when the overall market has been weak over the prior year.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "GP"},
        {"weight": -1.0, "primitive": "Mom12mOffSeason"}
      ],
      "regime": "MKT_TRAILING_12M_DOWN",
      "vol_target": false
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "MKT_TRAILING_12M_DOWN", "direction": "higher"},
      {"type": "size_segment", "segment": "mega", "direction": "stronger"},
      {"type": "subperiod_consistency"}
    ],
    "expected_annualized_sharpe": 0.65,
    "expected_decay_half_life_months": 20
  },
  {
    "name": "Supply Chain Anchored Momentum",
    "mechanism": "Stocks with above-average supplier momentum (iomom_supp), customer momentum (iomom_cust), and industry momentum (IndMom) benefit from positive real-economy transmission, resulting in more robust and persistent price trends. This cross-link strengthens the signal beyond each individual momentum component.",
    "expression": {
      "terms": [
        {"weight": 0.5, "primitive": "iomom_supp"},
        {"weight": 0.5, "primitive": "iomom_cust"},
        {"weight": 1.0, "primitive": "IndMom"}
      ],
      "regime": null,
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "correlation", "primitive": "IndMom", "bound": "below", "threshold": 0.3},
      {"type": "size_segment", "segment": "large", "direction": "stronger"},
      {"type": "international", "region": "developed_ex_us", "direction": "same_sign"}
    ],
    "expected_annualized_sharpe": 0.75,
    "expected_decay_half_life_months": 14
  },
  {
    "name": "Risk Aversion-Driven Carry",
    "mechanism": "Combining net payout yield (NetPayoutYield), Amihud illiquidity (Illiquidity), and volatility smirk (skew1), this composite captures the premium for holding liquid high-carry stocks with option-implied downside, especially in high VIX regimes when risk aversion is elevated.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "NetPayoutYield"},
        {"weight": -0.5, "primitive": "Illiquidity"},
        {"weight": 0.5, "primitive": "skew1"}
      ],
      "regime": "VIX_ABOVE_TRAILING_MEDIAN",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "VIX_ABOVE_TRAILING_MEDIAN", "direction": "higher"},
      {"type": "correlation", "primitive": "NetPayoutYield", "bound": "below", "threshold": 0.3},
      {"type": "size_segment", "segment": "mega", "direction": "stronger"}
    ],
    "expected_annualized_sharpe": 0.8,
    "expected_decay_half_life_months": 16
  },
  {
    "name": "Defensive Growth Compounders",
    "mechanism": "Firms with high organizational capital (OrgCap), strong earnings streaks (EarningsStreak), and low realized volatility (RealizedVol) represent sustainable compounders—defensive growth names likely to generate persistent alpha especially during periods of positive term spreads (economic expansions).",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "OrgCap"},
        {"weight": 0.5, "primitive": "EarningsStreak"},
        {"weight": -0.5, "primitive": "RealizedVol"}
      ],
      "regime": "TERM_SPREAD_POSITIVE",
      "vol_target": false
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "TERM_SPREAD_POSITIVE", "direction": "higher"},
      {"type": "size_segment", "segment": "large", "direction": "stronger"},
      {"type": "subperiod_consistency"}
    ],
    "expected_annualized_sharpe": 0.7,
    "expected_decay_half_life_months": 22
  }
]}
